"""Synthetic collections generated by the original Anki Python scheduler."""
from __future__ import annotations

import os
from pathlib import Path

from anki.collection import Collection
from anki.cards import Card
from anki import deck_config_pb2

DAY = 86400
NOW = 1793016000  # 2026-10-26 12:00 UTC, away from rollover.


def clock(seconds):
    path = Path(os.environ["ANKI_COMPARISON_CLOCK_FILE"])
    temporary = path.with_suffix(".next")
    temporary.write_text(str(round(seconds * 1000)))
    temporary.replace(path)


def seed(request):
    directory = Path(request["directory"])
    directory.mkdir(parents=True, exist_ok=False)
    clock(NOW - 120 * DAY)
    col = Collection(str(directory / "collection.anki2"))
    col.set_config("fsrs", True)
    col.set_config("fsrsShortTermWithStepsEnabled", True)
    parent = col.decks.id("Comparison")
    decks = [col.decks.id("Comparison::A"), col.decks.id("Comparison::B")]
    model = col.models.by_name("Basic (and reversed card)")
    for index in range(8):
        note = col.new_note(model)
        note.fields = [f"Synthetic front {index}", f"Synthetic back {index}"]
        col.add_note(note, decks[index % 2])
    ids = col.find_cards("")
    # Eight review cards, four learning, two relearning and two unseen cards.
    for index in list(range(8)) + [12, 13]:
        for days, rating in [(-60, 4), (-30, 3), (-10, 3)]:
            clock(NOW + days * DAY + index * 10)
            card = col.get_card(ids[index])
            card.start_timer()
            answer = col.sched.build_answer(card=card, states=col.sched.get_scheduling_states(card.id), rating=rating-1)
            answer.milliseconds_taken = 2400 + index * 100
            col.sched.answer_card(answer)
    for index in range(8, 14):
        clock(NOW - 600 + index)
        card = col.get_card(ids[index]); card.start_timer()
        answer = col.sched.build_answer(card=card, states=col.sched.get_scheduling_states(card.id), rating=0)
        answer.milliseconds_taken = 3300 + index * 100
        col.sched.answer_card(answer)
    clock(NOW)
    today = col.sched._timing_today().days_elapsed
    for index, cid in enumerate(ids[:8]):
        col.db.execute("update cards set due=? where id=?", today - index % 4, cid)
    for cfg in col.decks.all_config():
        cfg.update({"rwkvReviewInstantOrderEnabled": request["mode"] in ("instant", "both"),
                    "rwkvReviewEnabled": request["mode"] in ("curve", "both"),
                    "rwkvReviewAllowSameDayReview": True,
                    "rwkvReviewMinInterveningReviews": request.get("intervening", 1),
                    "rwkvReviewMinElapsedSecs": 0,
                    "rwkvReviewMinimumReviewsPerDay": 4,
                    "rwkvReviewRefreshInterval": request.get("refresh", 1),
                    "buryInterdayLearning": False,
                    "rwkvReviewEnforceGradeOrder": request.get("grade_order", True),
                    "fsrsVersion": request.get("fsrs", 1)})
        cfg["new"]["bury"] = False
        cfg["rev"]["bury"] = False
        if request.get("dynamic"):
            cfg.update({"fsrsDynamicDesiredRetentionEnabled": True,
                        "fsrsDynamicDesiredRetentionParams": [0.0]*15,
                        "fsrsDynamicDesiredRetentionWeights": [0.0,15.0],
                        "fsrsDynamicDesiredRetentionAvgDrs": [0.8,0.9],
                        "fsrsDynamicDesiredRetentionMin": 0.75,
                        "fsrsDynamicDesiredRetentionMax": 0.95})
        col.decks.update_config(cfg)
    if request.get("mixed"):
        config = col.decks.add_config_returning_id("Second preset")
        cfg = col.decks.get_config(config)
        first = col.decks.get_config(1)
        cfg.update({k: v for k,v in first.items() if k not in ("id", "name", "mod", "usn")})
        cfg["desiredRetention"] = 0.85
        cfg["fsrsVersion"] = 0
        col.decks.update_config(cfg)
        deck = col.decks.get(decks[1]); deck["conf"] = config; col.decks.update(deck)
    if request.get("dynamic_replay"):
        col.set_config("rwkvDynamicPresetReplay", True)
    col.decks.select(parent)
    metadata = {"deckId": str(parent), "decks": [str(v) for v in decks], "cards": [str(v) for v in ids], "now": NOW}
    col.close()
    return metadata
